  {v:"Wat is natuurlijke selectie?", o:["de best aangepaste krijgt meer jongen","de mens kiest welke dieren zich voortplanten","dieren kiezen zelf hun eigenschappen","alle dieren van een soort zijn gelijk"], g:0, u:"Volgens de evolutietheorie ontstaan zo in de loop van de tijd nieuwe soorten. Kunstmatige selectie is het fokken door de mens.", t:"examen-bio"},
  {v:"Wat is osmose?", o:["water gaat naar de zoutste kant","het verplaatsen van zuurstof door het bloed","het delen van een cel in tweeën","het verteren van vet in de darm"], g:0, u:"Daarom verwelken planten als ze te weinig water krijgen: de cellen verliezen water.", t:"examen-bio"},
  {v:"Wat is de functie van bladgroen?", o:["licht opvangen voor de fotosynthese","de plant beschermen tegen insecten","water opslaan","de bloem kleur geven"], g:0, u:"Zonder licht maakt de plant geen bladgroen: in het donker worden bladeren geel.", t:"examen-bio"},
  {v:"Waaruit bestaat een voedselweb?", o:["ketens die in elkaar overlopen","alle planten in een bos samen","de dieren van één soort","het voedsel van één dier"], g:0, u:"Een dier eet meestal meer dan één soort en wordt door meer dan één soort gegeten.", t:"examen-bio"},
  {v:"Wat is een populatie?", o:["alle dieren van één soort in een gebied","alle soorten samen in een gebied","de mensen die in een stad wonen","het aantal planten per meter"], g:0, u:"Alle reeën op de Veluwe vormen een populatie; alle organismen samen een levensgemeenschap.", t:"examen-bio"},
  {v:"Hoe past een kameel zich aan de woestijn aan?", o:["vet in de bult en weinig verlies","door in de zon te blijven staan","door alleen ’s nachts te eten","door heel veel water te drinken"], g:0, u:"Aanpassingen aan het milieu zijn erfelijk ontstaan door natuurlijke selectie.", t:"examen-bio"},
  {v:"Wat is de functie van de maag?", o:["voedsel kneden en zuur toevoegen","voedingsstoffen in het bloed opnemen","water uit de resten terughalen","de ontlasting tijdelijk bewaren"], g:0, u:"Het maagzuur doodt ook bacteriën. De opname gebeurt pas in de dunne darm.", t:"examen-bio"},
  {v:"Waarom is een dieet met veel vezels gezond?", o:["vezels houden de darmen aan het werk","vezels leveren heel veel energie","vezels worden snel opgenomen","vezels bevatten veel vitaminen"], g:0, u:"Vezels zitten in groente, fruit en volkoren; de mens kan ze niet verteren, maar ze zijn wel nuttig.", t:"examen-bio"},
  {v:"Wat gebeurt er bij inademing?", o:["het middenrif zakt, de borstkas wordt groter","het middenrif gaat juist omhoog staan","de longen persen de lucht naar buiten","de ribben zakken naar beneden"], g:0, u:"Uitademing is meestal passief: het middenrif ontspant en de borstholte wordt kleiner.", t:"examen-bio"},
  {v:"Wat is het verschil tussen ademhaling en verbranding?", o:["ademhaling is gaswisseling, verbranding levert energie","ademhaling gebeurt in de cel, verbranding in de longen","allebei betekenen ze precies hetzelfde ding","verbranding gebeurt alleen bij sporten"], g:0, u:"Ademhaling levert de zuurstof voor de verbranding en voert de koolstofdioxide af.", t:"examen-bio"},
  {v:"Waarom is roken slecht voor de longen?", o:["teer beschadigt de longblaasjes","rook maakt de longen juist schoon","rook vervangt de zuurstof volledig","roken versterkt de trilhaartjes"], g:0, u:"Nicotine is verslavend, koolmonoxide neemt de plaats van zuurstof in op hemoglobine.", t:"examen-bio"},
  {v:"Wat is bloedgroep-verdraagzaamheid bij een bloedtransfusie?", o:["het bloed mag niet klonteren","elke bloedgroep past op elke andere","alleen de leeftijd telt bij een transfusie","de hoeveelheid bloed is het enige dat telt"], g:0, u:"O-negatief is de universele donor; AB-positief kan van iedereen ontvangen.", t:"examen-bio"},
  {v:"Wat doen witte bloedcellen?", o:["ziekteverwekkers onschadelijk maken","zuurstof door het lichaam vervoeren","het bloed laten stollen bij een wond","het bloed zijn rode kleur geven"], g:0, u:"Bij een infectie neemt het aantal witte bloedcellen toe. Vaccinatie traint de afweer met een onschadelijke versie van de ziekteverwekker.", t:"examen-bio"},
  {v:"Wat is een vaccinatie?", o:["je krijgt verzwakte ziekteverwekkers","een medicijn tegen een bestaande ziekte","een pil tegen koorts en pijn","een onderzoek van je bloed"], g:0, u:"Bij een echte besmetting reageert de afweer dan snel: je wordt niet of minder ziek.", t:"examen-bio"},
  {v:"Wat is homeostase?", o:["het inwendige milieu constant houden","de groei van je lichaam in de puberteit","het vervangen van oude cellen","de samenwerking van hart en longen"], g:0, u:"Zweten bij warmte, rillen bij kou, insuline bij te veel glucose: regelkringen houden alles binnen grenzen.", t:"examen-bio"},
  {v:"Wat is de menstruatiecyclus?", o:["de maandelijkse cyclus van de eisprong","de groei van de baarmoeder in de zwangerschap","de dagelijkse cyclus van slapen en waken","de afgifte van melk na de bevalling"], g:0, u:"De cyclus wordt gestuurd door hormonen uit de hersenen en de eierstokken.", t:"examen-bio"},
  {v:"Wat is een soa?", o:["een infectie via seksueel contact","een ziekte die je van je ouders erft","een allergie voor bepaald voedsel","een tekort aan vitaminen"], g:0, u:"Een condoom beschermt tegen de meeste soa’s; de pil niet.", t:"examen-bio"},
  {v:"Wat is DNA?", o:["de drager van erfelijke informatie","een eiwit dat in je spieren zit","de kleurstof van je rode bloed","een medicijn tegen erfelijke ziekten"], g:0, u:"DNA-onderzoek wordt gebruikt bij verwantschap, misdaadonderzoek en erfelijke ziekten.", t:"examen-bio"},
  {v:"Wat is een dominant gen?", o:["een gen dat van beide ouders moet komen","een gen dat al tot uiting komt als het van één ouder komt","een gen dat alleen bij mannen voorkomt","een gen dat nooit tot uiting komt"], g:1, u:"Een recessief gen komt alleen tot uiting als het van beide ouders komt (bb).", t:"examen-bio"},
  {v:"Wat is genetische modificatie?", o:["het DNA van een organisme veranderen","het kruisen van twee rassen","het klonen van een heel dier","het kweken van planten in een kas"], g:0, u:"Voorstanders zien betere oogsten en medicijnen; tegenstanders zien risico’s voor natuur en gezondheid.", t:"examen-bio"}
